CREATE TABLE IF NOT EXISTS faculty_development_programs (id INT AUTO_INCREMENT PRIMARY KEY, dept VARCHAR(50) NOT NULL, title VARCHAR(255) NOT NULL, faculty_name VARCHAR(255) NOT NULL, organizer VARCHAR(255) NOT NULL, date_from DATE NOT NULL, date_to DATE NOT NULL, certificate_url VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
